sys_script.script:
(function executeRule(current, previous) {
    if (!current.status) {
        current.status = 'draft';
    }
    if (!current.approval_state) {
        current.approval_state = 'not_requested';
    }
})(current, previous);

(function executeRule(current, previous) {
    var validTransitions = {
        'draft': ['in_review'],
        'in_review': ['approved', 'rejected'],
        'approved': ['committed'],
        'rejected': ['draft', 'in_review'],
        'committed': ['rolled_back'],
        'rolled_back': ['draft']
    };

    var from = previous.status || 'draft';
    var to = current.status;

    var allowed = validTransitions[from] || [];
    if (allowed.indexOf(to) === -1) {
        gs.addErrorMessage('Invalid status transition: ' + from + ' to ' + to +
                          '. Allowed: ' + allowed.join(', '));
        current.setAbortAction(true);
    }
})(current, previous);

(function executeRule(current, previous) {
    current.committed_at = new GlideDateTime().getValue();
})(current, previous);

(function executeRule(current, previous) {
    if (!current.author) {
        current.author = gs.getUserID();
    }
})(current, previous);
